"""
Extract failed and ``fixme``-annotated tests from a Playwright JSON report.

The Playwright test runner writes a JSON report describing the outcome of every
spec, organised as a tree of (possibly nested) suites. This script walks that
tree and produces two small, stable artifacts that later CI steps aggregate:

  * ``failures.json``    - every failed/unexpected test with its error message
  * ``fixme_tests.json`` - every test annotated with ``fixme``

Both files are written to ``OUTPUT_DIR`` so that a downstream step can collect
them across browsers and workflow runs to spot flaky tests.

Environment variables:
  RESULTS_JSON - Path to the Playwright JSON report (may be missing)
  OUTPUT_DIR   - Directory to write ``failures.json`` and ``fixme_tests.json``
  BROWSER      - Browser the report was produced for (chromium/firefox/webkit)
  RUN_ID       - Identifier of the workflow run that produced the report
"""

from __future__ import annotations

import json
import os
from pathlib import Path

# Playwright reports a per-test ``status`` and a per-result ``status``. These are
# the values that mean "this test did not pass".
FAILURE_STATUSES = {"unexpected", "failed", "timedout", "timedOut", "interrupted"}

# Maximum length of an error message we keep before truncating.
MAX_ERROR_LENGTH = 300


def truncate_error(message: str) -> str:
    """Normalise and truncate a Playwright error message.

    Strips surrounding whitespace, collapses newlines into spaces and truncates
    to :data:`MAX_ERROR_LENGTH` characters, appending ``...`` when truncated
    (so a truncated message is exactly 303 characters long).
    """
    if not message:
        return ""
    normalized = message.strip().replace("\r\n", " ").replace("\n", " ").replace("\r", " ")
    if len(normalized) <= MAX_ERROR_LENGTH:
        return normalized
    return normalized[:MAX_ERROR_LENGTH] + "..."


def extract_test_title(spec: dict) -> str:
    """Build a human-readable title for a spec.

    Uses ``spec['location']['file']`` (defaulting to ``'unknown'``) as a prefix
    and joins the non-empty parts of ``spec['titlePath']`` with ``' > '``. When
    there are no title parts the file path alone is returned.
    """
    location = spec.get("location") or {}
    file = location.get("file") or "unknown"
    title_path = spec.get("titlePath") or []
    parts = [str(part) for part in title_path if part]
    if not parts:
        return file
    return f"{file}: {' > '.join(parts)}"


def _result_error(test: dict) -> str:
    """Return the first available error message from a test's results."""
    for result in test.get("results", []):
        error = result.get("error")
        if isinstance(error, dict) and error.get("message"):
            return truncate_error(error["message"])
        errors = result.get("errors")
        if isinstance(errors, list):
            for err in errors:
                if isinstance(err, dict) and err.get("message"):
                    return truncate_error(err["message"])
                if isinstance(err, str) and err:
                    return truncate_error(err)
        if isinstance(error, str) and error:
            return truncate_error(error)
    return ""


def _test_failed(test: dict) -> bool:
    """Whether a Playwright test object represents a failure."""
    if test.get("status") in FAILURE_STATUSES:
        return True
    return any(result.get("status") in FAILURE_STATUSES for result in test.get("results", []))


def extract_failures(suites: list) -> list:
    """Recursively collect failed/unexpected tests from Playwright suites."""
    failures: list = []
    for suite in suites or []:
        for spec in suite.get("specs", []):
            spec_file = (spec.get("location") or {}).get("file") or "unknown"
            for test in spec.get("tests", []):
                if _test_failed(test):
                    failures.append(
                        {
                            "test": extract_test_title(spec),
                            "status": test.get("status", ""),
                            "error": _result_error(test),
                            "spec_file": spec_file,
                        }
                    )
        failures.extend(extract_failures(suite.get("suites", [])))
    return failures


def extract_fixme_tests(suites: list) -> list:
    """Recursively collect tests annotated with ``fixme`` from Playwright suites."""
    fixme_tests: list = []
    for suite in suites or []:
        for spec in suite.get("specs", []):
            for test in spec.get("tests", []):
                annotations = test.get("annotations") or []
                if any(isinstance(a, dict) and a.get("type") == "fixme" for a in annotations):
                    fixme_tests.append(
                        {
                            "test": extract_test_title(spec),
                            "status": test.get("status", ""),
                            "annotations": annotations,
                        }
                    )
        fixme_tests.extend(extract_fixme_tests(suite.get("suites", [])))
    return fixme_tests


