"""
Analyse aggregated end-to-end (Playwright) test results and build a Slack report.

Downstream of :mod:`extract_e2e_test_results`, the CI workflow collects the
per-browser/per-run ``failures.json`` and ``fixme_tests.json`` artifacts and
aggregates them into:

  * ``failures_by_test``  - mapping of test title -> list of failure records
  * ``fixme_tests``       - mapping of test title -> fixme record
  * ``runs``              - list of the workflow runs that were inspected
  * ``runs_with_data``    - number of (run x browser) data points with results

This module turns that aggregate into a Slack Block Kit message that highlights
which tests fail often enough to be worth marking as ``fixme`` (the "flaky
candidates") and reminds reviewers of the tests already marked ``fixme``.
"""

from __future__ import annotations

# Slack channel the report is posted to.
SLACK_CHANNEL = "airflow-3-ui"

# A test must fail on more than this fraction of the runs-with-data before it is
# considered a candidate for being marked as needing a fix. A test that fails
# very rarely (e.g. 1 failure across 10 runs on 3 browsers -> ~3%) is ignored.
MIN_FAILURE_RATE = 0.1


def escape_slack_mrkdwn(text: str) -> str:
    """Escape the characters Slack treats specially in ``mrkdwn`` text.

    ``&`` must be escaped first so that the ampersands introduced while escaping
    ``<`` and ``>`` are not escaped a second time.
    """
    return str(text).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def _failure_count(value) -> int:
    """Best-effort count of failures recorded for a single test."""
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, (list, tuple, set)):
        return len(value)
    if isinstance(value, dict):
        if "count" in value and isinstance(value["count"], int):
            return value["count"]
        for key in ("failures", "occurrences", "runs"):
            if isinstance(value.get(key), (list, tuple)):
                return len(value[key])
        return 1
    return 0


def identify_flaky_candidates(failures_by_test: dict, runs_with_data: int) -> list:
    """Identify tests failing often enough to be candidates for a ``fixme`` mark.

    Returns a list of ``{"test", "failure_count", "failure_rate"}`` dicts for
    every test whose failure rate exceeds :data:`MIN_FAILURE_RATE`, sorted by
    ``failure_rate`` in descending order. Returns an empty list when there is no
    data (``runs_with_data`` is ``0``) or no recorded failures.
    """
    if not failures_by_test or not runs_with_data:
        return []

    candidates = []
    for test, value in failures_by_test.items():
        failure_count = _failure_count(value)
        if failure_count <= 0:
            continue
        failure_rate = failure_count / runs_with_data
        if failure_rate > MIN_FAILURE_RATE:
            candidates.append(
                {
                    "test": test,
                    "failure_count": failure_count,
                    "failure_rate": failure_rate,
                }
            )

    candidates.sort(key=lambda candidate: candidate["failure_rate"], reverse=True)
    return candidates


def _representative_error(value) -> str:
    """Pull a representative error message out of an aggregated failure record."""
    if isinstance(value, (list, tuple)) and value:
        first = value[0]
        if isinstance(first, dict):
            return str(first.get("error", ""))
        return str(first)
    if isinstance(value, dict):
        return str(value.get("error", ""))
    return ""


def _fixme_test_names(fixme_tests: dict) -> list:
    """Return the list of test names carried by an aggregated fixme structure."""
    if not fixme_tests:
        return []
    if isinstance(fixme_tests, dict):
        nested = fixme_tests.get("fixme_tests")
        if isinstance(nested, list):
            return [item.get("test", "") if isinstance(item, dict) else str(item) for item in nested]
        return list(fixme_tests.keys())
    if isinstance(fixme_tests, (list, tuple)):
        return [item.get("test", "") if isinstance(item, dict) else str(item) for item in fixme_tests]
    return []


def _section(text: str) -> dict:
    """Build a Slack ``section`` block from ``mrkdwn`` text."""
    return {"type": "section", "text": {"type": "mrkdwn", "text": text}}


