        {
            "type": "header",
            "text": {"type": "plain_text", "text": "Airflow UI E2E Flaky Test Report"},
        },
        _section(
            f"*Repository:* {escape_slack_mrkdwn(repo)}\n"
            f"*Runs analysed:* {total_runs} (with data: {runs_with_data})"
        ),
    ]

