    if failures_by_test:
        failure_lines = []
        for test, value in failures_by_test.items():
            count = _failure_count(value)
            error = _representative_error(value)
            line = f"• *{escape_slack_mrkdwn(test)}* ({count} failure(s))"
            if error:
